import csv
import io

def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    def normalize(row):
        if len(row) > 5:
            return row[:3] + [",".join(row[3:-1]), row[-1]]
        return row + [""] * (5 - len(row))

    columns = normalize(records[0])
    columns[0] = columns[0].lstrip("\ufeff")
    return {"columns": columns, "rows": [normalize(row) for row in records[1:]]}
